import {account,mountAccountLink} from './account-client.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'尚无记录';let offset=0,search='',total=0,request=0;
async function list(){const id=++request;$('#admin-message').textContent='正在读取…';try{const v=await account.adminUsers(search,offset);if(id!==request)return;total=v.total;$('#admin-message').textContent=`共 ${total} 个账户 · 时间显示为北京时间`;$('#admin-users').innerHTML=`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>昵称</th><th>注册时间</th><th>最近活动</th><th>页面访问次数</th><th>最近终端</th><th>已做 / 收藏</th><th>详情</th></tr></thead><tbody>${v.users.map(u=>`<tr><td>${esc(u.nickname)}${u.is_admin?' · 管理员':''}</td><td>${date(u.created_at)}</td><td>${date(u.last_seen_at)}${u.last_seen_at&&Date.now()-Date.parse(u.last_seen_at)<300000?' · 近5分钟活跃':''}</td><td>${u.visits}</td><td>${({mobile:'手机',tablet:'平板',desktop:'电脑'})[u.last_device]||'—'}</td><td>${u.done_count} / ${u.saved_count}</td><td><button class="text-button" data-user="${u.id}" data-name="${esc(u.nickname)}">最近活动 ↗</button></td></tr>`).join('')||'<tr><td colspan="7">没有找到符合条件的账户</td></tr>'}</tbody></table></div><div class="pagination"><button class="secondary" id="admin-prev" ${offset===0?'disabled':''}>← 上一页</button><span>第 ${Math.floor(offset/30)+1} 页</span><button class="secondary" id="admin-next" ${offset+30>=total?'disabled':''}>下一页 →</button></div>`;$('#admin-prev').onclick=()=>{offset=Math.max(0,offset-30);list();};$('#admin-next').onclick=()=>{offset+=30;list();};}catch(e){$('#admin-message').textContent=e.message;}}
await account.ready;await mountAccountLink();if(!account.enabled)$('#admin-content').innerHTML='<h1>管理员后台尚未启用</h1><p>账户数据库尚未连接，当前没有真实用户访问数据。</p>';else if(!account.user)location.replace('account.html?next=admin.html');else if(!account.user.is_admin)$('#admin-content').innerHTML='<h1>没有管理员权限</h1><p>普通账户只能访问自己的记录。</p><a href="account.html">返回个人账户</a>';else{$('#admin-content').innerHTML='<div class="breadcrumb">管理空间 / 访问统计</div><h1>每个账户的学习足迹。</h1><p class="admin-hint">查看注册、最近活动、页面访问次数及已做/收藏数量。详情保留每人最近200条活动；访问总次数持续累计。后台不包含用户密码。统计依据登录后浏览器上报的活动，不等同于服务器完整请求日志。</p><form class="admin-filter" id="admin-search"><input id="admin-query" placeholder="按昵称搜索" maxlength="40" aria-label="昵称"><button class="primary">搜索</button><button class="secondary" type="button" id="admin-refresh">刷新</button></form><p id="admin-message" role="status"></p><div id="admin-users"></div>';$('#admin-search').onsubmit=e=>{e.preventDefault();search=$('#admin-query').value.trim();offset=0;list();};$('#admin-refresh').onclick=list;await list();account.activity('visit','admin').catch(()=>{});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-user]');if(!b)return;$('#activity-title').textContent=b.dataset.name+' · 最近活动';$('#activity-content').textContent='正在读取…';$('#activity-dialog').showModal();try{const rows=await account.adminActivity(b.dataset.user);$('#activity-content').innerHTML='<table class="admin-table"><thead><tr><th>时间</th><th>活动</th><th>页面</th><th>题号</th><th>终端</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${date(r.occurred_at)}</td><td>${({visit:'访问页面',solution:'查看解析',book:'阅读资料'})[r.kind]||esc(r.kind)}</td><td>${esc(r.page)}</td><td>${esc(r.question_id||'—')}</td><td>${esc(r.device)}</td></tr>`).join('')+'</tbody></table>';}catch(err){$('#activity-content').textContent=err.message;}});$('#activity-close').onclick=()=>$('#activity-dialog').close();
